class Node:
    def __init__(self, val=0, nxt=None):
        self.val = val
        self.next = nxt


def add_two_numbers(l1, l2):
    dummy = tail = Node(0)
    carry = 0
    while l1 or l2 or carry:
        total = carry
        if l1:
            total += l1.val
            l1 = l1.next
        if l2:
            total += l2.val
            l2 = l2.next
        carry, digit = divmod(total, 10)
        tail.next = Node(digit)
        tail = tail.next
    return dummy.next
